import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

// ─────────────────────────────────────────────────────────────────────────────
// CERTIFICATIONS DATA
// ─────────────────────────────────────────────────────────────────────────────
// HOW TO EDIT:
//   - Update title, org, year, credential, image, and tags below.
//   - `completed: false` hides the card entirely — use this for in-progress certs.
//   - `image`: path to a certificate image in /public/images/certs/
//              Can be a badge, a certificate screenshot, or a logo.
//              Recommended size: 800×500px (shown at 16:9 ratio in the card)
//   - `credential`: URL to verify the cert (null = shows "credential pending")
// ─────────────────────────────────────────────────────────────────────────────
const certifications = [
  {
    id: "cert-01",
    completed: true,                           // ← set false to hide
    title: "Web Development Fundamentals",
    org: "Issuing Organization",
    year: "2024",
    credential: null,                          // ← replace with your verify URL
    // Replace this image with your actual certificate or badge
    // Path is relative to /public/  →  drop file in public/images/certs/
    image: "/images/certs/cert-web-dev.svg",
    imageAlt: "Web Development Fundamentals certificate",
    tags: ["PHP", "MySQL", "HTML/CSS", "JavaScript"],
  },
  {
    id: "cert-02",
    completed: true,
    title: "Mobile App Development",
    org: "Issuing Organization",
    year: "2024",
    credential: null,
    // Replace this image with your actual certificate or badge
    image: "/images/certs/cert-mobile-dev.svg",
    imageAlt: "Mobile App Development certificate",
    tags: ["Flutter", "Firebase", "Dart"],
  },
  {
    id: "cert-03",
    completed: true,
    title: "Database Management & Design",
    org: "Issuing Organization",
    year: "2023",
    credential: null,
    // Replace this image with your actual certificate or badge
    image: "/images/certs/cert-database.svg",
    imageAlt: "Database Management & Design certificate",
    tags: ["SQL", "Normalization", "Query Optimization"],
  },
  // ── Template for adding a new certification ───────────────────────────────
  // {
  //   id: "cert-04",
  //   completed: false,                       ← change to true when earned
  //   title: "Your Certification Title",
  //   org: "Issuing Organization",
  //   year: "2025",
  //   credential: "https://verify.example.com/your-id",
  //   image: "/images/certs/your-cert.png",
  //   imageAlt: "Description of the certificate image",
  //   tags: ["Skill 1", "Skill 2"],
  // },
];

// ─────────────────────────────────────────────────────────────────────────────
// CertCard
// ─────────────────────────────────────────────────────────────────────────────
function CertCard({ cert, isDark }) {
  return (
    <article
      className={`group flex flex-col border transition-all duration-300 overflow-hidden
        ${isDark
          ? "bg-ink-800 border-wire hover:border-ink-500"
          : "bg-white border-wire-light hover:border-gray-300 hover:shadow-sm"}`}
    >
      {/* ── CERTIFICATE IMAGE ──────────────────────────────────────────────
          To replace: update the `image` field in the certifications array above.
          Drop your file into /public/images/certs/ and set the path.
          Supported formats: .png  .jpg  .webp  .svg
          Recommended size: 800×500px (16:9 ratio)
      ─────────────────────────────────────────────────────────────────── */}
      <div className="relative overflow-hidden" style={{ aspectRatio: "16/9" }}>
        <img
          src={cert.image}
          alt={cert.imageAlt}
          width="800"
          height="500"
          loading="lazy"
          className="w-full h-full object-cover transition-transform duration-500 ease-out group-hover:scale-[1.03]"
        />
        {/* Year badge — top right corner */}
        <div className={`absolute top-3 right-3 font-mono text-xs px-2.5 py-1 tracking-wider
          ${isDark ? "bg-ink-950/90 text-stone-400 border border-wire" : "bg-white/90 text-gray-500 border border-wire-light"}`}>
          {cert.year}
        </div>
      </div>

      {/* ── CARD BODY ─────────────────────────────────────────────────── */}
      <div className="flex flex-col flex-1 p-5">

        {/* Title + org */}
        <div className="mb-4">
          <h3 className={`font-display font-semibold text-base leading-snug mb-1
            ${isDark ? "text-stone-200" : "text-gray-900"}`}>
            {cert.title}
          </h3>
          <p className={`text-sm ${isDark ? "text-stone-500" : "text-gray-500"}`}>
            {cert.org}
          </p>
        </div>

        {/* Tags */}
        <div className="flex flex-wrap gap-1.5 mb-5">
          {cert.tags.map((tag) => (
            <span key={tag} className="tag">{tag}</span>
          ))}
        </div>

        {/* Credential link — pinned to bottom */}
        <div className={`mt-auto pt-4 border-t flex items-center justify-between
          ${isDark ? "border-wire" : "border-wire-light"}`}>
          <div className={`flex items-center gap-1.5 font-mono text-xs ${isDark ? "text-stone-600" : "text-gray-400"}`}>
            <span className="text-accent-glow">✓</span>
            Completed
          </div>

          {cert.credential ? (
            <a
              href={cert.credential}
              target="_blank"
              rel="noopener noreferrer"
              className="font-mono text-xs text-accent-glow hover:text-accent transition-colors flex items-center gap-1.5 tracking-wider"
              aria-label={`Verify ${cert.title} credential`}
            >
              Verify Credential
              <svg width="10" height="10" viewBox="0 0 24 24" fill="none"
                   stroke="currentColor" strokeWidth="2" aria-hidden="true">
                <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6M15 3h6v6M10 14L21 3"/>
              </svg>
            </a>
          ) : (
            <span className={`font-mono text-xs ${isDark ? "text-stone-700" : "text-gray-300"}`}>
              Credential pending
            </span>
          )}
        </div>
      </div>
    </article>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Certifications section
// ─────────────────────────────────────────────────────────────────────────────
export default function Certifications() {
  const { ref, revealed } = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  // Only show completed certifications
  const completed = certifications.filter((c) => c.completed);

  // Don't render the section at all if there are no completed certs
  if (completed.length === 0) return null;

  return (
    <section
      id="certifications"
      className={`py-28 border-t transition-colors duration-300
        ${isDark ? "bg-ink-950 border-wire" : "bg-paper-50 border-wire-light"}`}
    >
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Certifications</p>
          <h2 className={`section-title text-3xl sm:text-4xl lg:text-5xl max-w-xl
            ${isDark ? "text-stone-200" : "text-gray-900"}`}>
            Formal recognition<br />
            <span className={isDark ? "text-stone-500" : "text-gray-400"}>of applied skills.</span>
          </h2>
          {/* To edit: update the certifications[] array at the top of this file */}
          {/* To hide a cert: set completed: false */}
        </div>

        <div
          ref={ref}
          className={`grid sm:grid-cols-2 lg:grid-cols-3 gap-5
            ${revealed ? "fade-up visible" : "fade-up"}`}
        >
          {completed.map((cert) => (
            <CertCard key={cert.id} cert={cert} isDark={isDark} />
          ))}
        </div>

        <p className={`mt-10 font-mono text-xs tracking-wider
          ${isDark ? "text-stone-700" : "text-gray-400"}`}>
          // {certifications.length - completed.length > 0
            ? `${certifications.length - completed.length} certification(s) in progress — shown when completed`
            : "Additional certifications added as completed"}
        </p>
      </div>
    </section>
  );
}
